#!/usr/bin/env python3
"""reproduce_paper.py - single-file reproduction of the Electronics Letters paper
"Predicting the gate cost of digital chaotic systems". Needs Python 3, NumPy, Matplotlib.
Recomputed from gate-level netlists: Table 1 gate counts and fits, a and b, the tent-map
rule, the architecture swap and Fig. 1. Stored results: Fig. 2 energy, fidelity, Vivado LUTs.
Usage: python reproduce_paper.py [--skip-slow] [--no-plots]
"""
_SRC = {'chua_min': "# Minimal gate-level Chua circuit.\n# Only AND/OR/XOR/NOT. The design is flattened into one netlist with constant\n# folding and structural hashing, so it no longer mirrors the arithmetic.\n#\n# Algebraic rewrite used to build it (dt = 2^-7, alpha=15.6, beta=28, m0=-8/7, m1=-5/7):\n#   (|x+1| - |x-1|)/2 = sat(x) = clamp(x,-1,1)  -> pure bit logic, no adders\n#   x' = x + cxx*x + cxy*y + cxs*sat(x)          (dt and alpha folded into constants)\n#   y' = y + (x - y + z) * 2^-7\n#   z' = z - 28*2^-7 * y\nW, FRAC = 20, 16            # 4 integer bits (|x|,|z| < 8) + 16 fraction bits\n\nclass Net:\n    def __init__(s): s.ops=[]; s.h={}\n    def _g(s,op,a,b=None):\n        k=(op,a,b); \n        if k in s.h: return s.h[k]\n        s.ops.append(k); n=('n',len(s.ops)-1); s.h[k]=n; return n\n    def NOT(s,a):\n        if a in (0,1): return 1-a\n        if a[0]=='n' and s.ops[a[1]][0]=='NOT': return s.ops[a[1]][1]\n        return s._g('NOT',a)\n    def AND(s,a,b):\n        if a==0 or b==0: return 0\n        if a==1: return b\n        if b==1: return a\n        if a==b: return a\n        if a>b: a,b=b,a\n        return s._g('AND',a,b)\n    def OR(s,a,b):\n        if a==1 or b==1: return 1\n        if a==0: return b\n        if b==0: return a\n        if a==b: return a\n        if a>b: a,b=b,a\n        return s._g('OR',a,b)\n    def XOR(s,a,b):\n        if a==0: return b\n        if b==0: return a\n        if a==1: return s.NOT(b)\n        if b==1: return s.NOT(a)\n        if a==b: return 0\n        if a>b: a,b=b,a\n        return s._g('XOR',a,b)\n\ndef build(digits_budget=5, G=4):\n    g=Net()\n    X=[('x',i) for i in range(W)]; Y=[('y',i) for i in range(W)]; Z=[('z',i) for i in range(W)]\n    def add(A,B,cin=0):\n        o=[];c=cin\n        for a,b in zip(A,B):\n            s1=g.XOR(a,b); o.append(g.XOR(s1,c)); c=g.OR(g.AND(a,b),g.AND(s1,c))\n        return o\n    def sub(A,B): return add(A,[g.NOT(b) for b in B],1)\n    def asr(A,k): return A[k:]+[A[-1]]*k\n    def shl(A,k): return [0]*k+A[:W-k]\n    # sat(x) = clamp(x,-1,1), pure logic\n    s=X[-1]\n    inr=1\n    for i in range(FRAC,W-1): inr=g.AND(inr, g.NOT(g.XOR(X[i],s)))\n    SAT=[g.AND(inr,X[i]) for i in range(FRAC)] + [g.OR(g.NOT(inr),s)] + [s]*(W-FRAC-1)\n    def csd(c):\n        v=round(c*(1<<FRAC)); t=[]; i=0\n        while v:\n            if v&1: d=2-(v&3); t.append((d,i)); v-=d\n            v>>=1; i+=1\n        t.sort(key=lambda q:-q[1]); return t\n    def lin(acc, terms):            # acc + sum(coef*signal), with G guard bits, rounded once\n        WW=W+G\n        up=lambda A:[0]*G+A\n        acc=up(acc); acc[G-1]=1      # +half LSB -> round to nearest at the end\n        def shl(A,k): return [0]*k+A[:WW-k]\n        def asr(A,k): return A[k:]+[A[-1]]*k\n        for sig,c in terms:\n            sig=up(sig)\n            ds=csd(c)\n            if digits_budget: ds=ds[:digits_budget]\n            for d,i in ds:\n                k=i-FRAC; t=shl(sig,k) if k>=0 else asr(sig,-k)\n                acc = add(acc,t) if d>0 else sub(acc,t)\n        return acc[G:]\n    dta=15.6/128; m0,m1=-8/7,-5/7\n    Xn=lin(X,[(X,-dta*(1+m1)),(Y,dta),(SAT,-dta*(m0-m1))])\n    Yn=add(Y, asr(add(sub(X,Y),Z),7))\n    Zn=lin(Z,[(Y,-28/128)])\n    return g,Xn,Yn,Zn\n\ndef simulate(g,outs,state):\n    val={}\n    def v(a):\n        if a in (0,1): return a\n        if a[0]=='n': return val[a[1]]\n        return state[a[0]][a[1]]\n    for i,(op,a,b) in enumerate(g.ops):\n        val[i]={'NOT':lambda:1-v(a),'AND':lambda:v(a)&v(b),'OR':lambda:v(a)|v(b),'XOR':lambda:v(a)^v(b)}[op]()\n    return {k:[v(bit) for bit in o] for k,o in zip('xyz',outs)}\n\ndef tob(x): v=round(x*(1<<FRAC))&((1<<W)-1); return [(v>>i)&1 for i in range(W)]\ndef tof(A): v=sum(b<<i for i,b in enumerate(A)); return (v-(1<<W) if A[-1] else v)/(1<<FRAC)\n", 'zoo': '# 20 chaotic systems (10 maps, 10 flows), each written ONCE against a backend,\n# run either in floating point or as an optimised AND/OR/XOR/NOT netlist.\nimport math\nfrom chua_min import Net\n\nclass FloatB:\n    def K(s,c): return c\n    def add(s,a,b): return a+b\n    def sub(s,a,b): return a-b\n    def mul(s,a,b): return a*b\n    def abs(s,a): return abs(a)\n    def lin(s,acc,terms,const=0.0): return acc+const+sum(c*v for v,c in terms)\n    def frac(s,a): return a%1.0\n    def shl(s,a,k): return a*2**k\n    def asr(s,a,k): return a/2**k\n    def ge_half(s,a): return 0.5 if a>=0.5 else 0.0\n    def sat(s,a): return max(-1.0,min(1.0,a))\n\nclass BitB:\n    def __init__(s,W,I,digits=None,G=4):\n        s.W,s.I,s.F,s.G,s.d=W,I,W-I,G,digits; s.g=Net()\n    def _add(s,A,B,cin=0):\n        g=s.g;o=[];c=cin\n        for a,b in zip(A,B):\n            x=g.XOR(a,b); o.append(g.XOR(x,c)); c=g.OR(g.AND(a,b),g.AND(x,c))\n        return o\n    def K(s,c,W=None,F=None):\n        W=W or s.W; F=s.F if F is None else F\n        v=round(c*(1<<F))&((1<<W)-1); return [(v>>i)&1 for i in range(W)]\n    def add(s,A,B): return s._add(A,B)\n    def sub(s,A,B): return s._add(A,[s.g.NOT(b) for b in B],1)\n    def shl(s,A,k): return [0]*k+A[:len(A)-k]\n    def asr(s,A,k): return A[k:]+[A[-1]]*k\n    def abs(s,A): return [s.g.XOR(a,A[-1]) for a in A]\n    def frac(s,A): return A[:s.F]+[0]*s.I\n    def ge_half(s,A): return [0]*(s.F-1)+[A[s.F-1]]+[0]*s.I\n    def sat(s,A):\n        g=s.g; sg=A[-1]; inr=1\n        for i in range(s.F,s.W-1): inr=g.AND(inr,g.NOT(g.XOR(A[i],sg)))\n        return [g.AND(inr,A[i]) for i in range(s.F)]+[g.OR(g.NOT(inr),sg)]+[sg]*(s.I-1)\n    def _csd(s,c):\n        v=round(c*(1<<(s.F+s.G))); t=[]; i=0\n        while v:\n            if v&1: d=2-(v&3); t.append((d,i)); v-=d\n            v>>=1; i+=1\n        t.sort(key=lambda q:-q[1]); return t[:s.d] if s.d else t\n    def lin(s,acc,terms,const=0.0):\n        G=s.G; WW=s.W+G; up=lambda A:[0]*G+A\n        acc=up(acc); acc[G-1]=1\n        if const: acc=s._add(acc,s.K(const,WW,s.F+G))\n        for sig,c in terms:\n            v=up(sig)\n            for d,i in s._csd(c):\n                k=i-(s.F+G); t=s.shl(v,k) if k>=0 else s.asr(v,-k)\n                acc=s._add(acc,t) if d>0 else s.sub(acc,t)\n        return acc[G:]\n    def mul(s,A,B):\n        g=s.g; W,F=s.W,s.F; HI=F+W\n        ext=lambda k: A[k] if 0<=k<W else (A[-1] if k>=W else 0)\n        acc=[0]*HI\n        for j in range(W//2):\n            bh,bm=B[2*j+1],B[2*j]; bl=B[2*j-1] if j else 0\n            one=g.XOR(bm,bl)\n            two=g.OR(g.AND(bh,g.AND(g.NOT(bm),g.NOT(bl))),g.AND(g.NOT(bh),g.AND(bm,bl)))\n            pp=[g.XOR(g.OR(g.AND(one,ext(c-2*j)),g.AND(two,ext(c-2*j-1))),bh) for c in range(2*j,HI)]\n            acc[2*j:]=s._add(acc[2*j:],pp,bh)\n        return acc[F:HI]\n\nZ=lambda B:B.K(0.0)\n# ---------------- 10 maps ----------------\ndef logistic(B,x):       return [B.lin(Z(B),[(B.mul(x,B.sub(B.K(1.0),x)),3.9375)])]\ndef tent(B,x):           return [B.lin(Z(B),[(B.sub(B.K(.5),B.abs(B.sub(x,B.K(.5)))),1.9921875)])]\ndef bernoulli(B,x):      return [B.frac(B.shl(x,1))]\ndef henon(B,x,y):        return [B.lin(y,[(B.mul(x,x),-1.4)],1.0), B.lin(Z(B),[(x,.3)])]\ndef lozi(B,x,y):         return [B.lin(y,[(B.abs(x),-1.75)],1.0), B.asr(x,1)]\ndef cat(B,x,y):\n    xn=B.frac(B.add(x,y)); return [xn, B.frac(B.add(xn,y))]\ndef baker(B,x,y):        return [B.frac(B.shl(x,1)), B.add(B.asr(B.frac(y),1),B.ge_half(x))]\ndef gingerbread(B,x,y):  return [B.lin(B.abs(x),[(y,-1)],1.0), x]\ndef duffing_map(B,x,y):  return [y, B.lin(Z(B),[(x,-.2),(y,2.75),(B.mul(B.mul(y,y),y),-1)])]\ndef tinkerbell(B,x,y):\n    return [B.lin(Z(B),[(B.mul(x,x),1),(B.mul(y,y),-1),(x,.9),(y,-.6013)]),\n            B.lin(Z(B),[(B.mul(x,y),2),(x,2),(y,.5)])]\n# ---------------- 10 flows (Euler, dt = 2^-k) ----------------\ndef euler(B,s,d,dt): return [B.lin(a,[(b,dt)]) for a,b in zip(s,d)]\ndef lorenz(B,x,y,z):\n    dt=2**-7; return [B.lin(x,[(B.sub(y,x),10*dt)]),\n        B.lin(y,[(B.mul(x,B.sub(B.K(28.),z)),dt),(y,-dt)]),\n        B.lin(z,[(B.mul(x,y),dt),(z,-8/3*dt)])]\ndef rossler(B,x,y,z):\n    dt=2**-8; return [B.lin(x,[(y,-dt),(z,-dt)]), B.lin(y,[(x,dt),(y,.2*dt)]),\n        B.lin(z,[(B.mul(z,B.sub(x,B.K(5.7))),dt)],.2*dt)]\ndef chua(B,x,y,z):\n    dt=2**-7; a=15.6; m0,m1=-8/7,-5/7\n    return [B.lin(x,[(x,-dt*a*(1+m1)),(y,dt*a),(B.sat(x),-dt*a*(m0-m1))]),\n            B.lin(y,[(x,dt),(y,-dt),(z,dt)]), B.lin(z,[(y,-28*dt)])]\ndef chen(B,x,y,z):\n    dt=2**-9; return [B.lin(x,[(B.sub(y,x),35*dt)]),\n        B.lin(y,[(x,-7*dt),(B.mul(x,z),-dt),(y,28*dt)]),\n        B.lin(z,[(B.mul(x,y),dt),(z,-3*dt)])]\ndef lu(B,x,y,z):\n    dt=2**-9; return [B.lin(x,[(B.sub(y,x),36*dt)]),\n        B.lin(y,[(B.mul(x,z),-dt),(y,20*dt)]),\n        B.lin(z,[(B.mul(x,y),dt),(z,-3*dt)])]\ndef halvorsen(B,x,y,z):\n    dt=2**-9; a=1.4\n    return [B.lin(x,[(x,-a*dt),(y,-4*dt),(z,-4*dt),(B.mul(y,y),-dt)]),\n            B.lin(y,[(y,-a*dt),(z,-4*dt),(x,-4*dt),(B.mul(z,z),-dt)]),\n            B.lin(z,[(z,-a*dt),(x,-4*dt),(y,-4*dt),(B.mul(x,x),-dt)])]\ndef rikitake(B,x,y,z):\n    dt=2**-8; return [B.lin(x,[(x,-2*dt),(B.mul(y,z),dt)]),\n        B.lin(y,[(y,-2*dt),(B.mul(B.sub(z,B.K(5.)),x),dt)]),\n        B.lin(z,[(B.mul(x,y),-dt)],dt)]\ndef arneodo(B,x,y,z):\n    dt=2**-8; return [B.lin(x,[(y,dt)]), B.lin(y,[(z,dt)]),\n        B.lin(z,[(x,5.5*dt),(y,-3.5*dt),(z,-dt),(B.mul(B.mul(x,x),x),-dt)])]\ndef shimizu(B,x,y,z):\n    dt=2**-7; return [B.lin(x,[(y,dt)]),\n        B.lin(y,[(B.mul(B.sub(B.K(1.),z),x),dt),(y,-.75*dt)]),\n        B.lin(z,[(z,-.45*dt),(B.mul(x,x),dt)])]\ndef sprott_jerk(B,x,y,z):\n    dt=2**-6; return [B.lin(x,[(y,dt)]), B.lin(y,[(z,dt)]),\n        B.lin(z,[(z,-.6*dt),(y,-dt),(B.abs(x),dt)],-dt)]\n\n# name, fn, integer bits, initial state, kind\nSYSTEMS=[\n ("Logistic (r=3.9375)",logistic,2,(0.3,),"map"),\n ("Tent (mu=1.99)",tent,2,(0.3,),"map"),\n ("Bernoulli / dyadic",bernoulli,2,(0.3,),"map"),\n ("Henon",henon,3,(0.1,0.1),"map"),\n ("Lozi (a=1.75)",lozi,3,(0.1,0.1),"map"),\n ("Arnold\'s cat",cat,2,(0.3,0.7),"map"),\n ("Baker\'s",baker,2,(0.3,0.7),"map"),\n ("Gingerbreadman",gingerbread,5,(-0.1,0.0),"map"),\n ("Duffing map",duffing_map,5,(0.1,0.1),"map"),\n ("Tinkerbell",tinkerbell,3,(-0.72,-0.64),"map"),\n ("Lorenz",lorenz,12,(1,1,1),"flow"),\n ("Rossler",rossler,10,(1,1,0),"flow"),\n ("Chua",chua,4,(0.7,0,0),"flow"),\n ("Chen",chen,13,(-10,0,37),"flow"),\n ("Lu",lu,12,(1,1,1),"flow"),\n ("Halvorsen",halvorsen,10,(-1.48,-1.51,2.04),"flow"),\n ("Rikitake",rikitake,8,(1,0,0.5),"flow"),\n ("Arneodo",arneodo,8,(0.2,0.2,-0.75),"flow"),\n ("Shimizu-Morioka",shimizu,4,(0.1,0,0),"flow"),\n ("Sprott jerk circuit",sprott_jerk,4,(0.1,0,0),"flow"),\n]\n\ndef build(fn,W,I,nv,digits=None):\n    B=BitB(W,I,digits); st=[[(chr(97+v),i) for i in range(W)] for v in range(nv)]\n    outs=fn(B,*st); return B,outs\n\ndef compile_net(B,outs,nv):\n    """Turn the netlist into one Python function on bit lists (fast simulation)."""\n    def r(a):\n        if a in (0,1): return str(a)\n        return f"v{a[1]}" if a[0]==\'n\' else f"{a[0]}[{a[1]}]"\n    L=[f"def step({\',\'.join(chr(97+v) for v in range(nv))}):"]\n    for i,(op,a,b) in enumerate(B.g.ops):\n        e = f"1-{r(a)}" if op==\'NOT\' else f"{r(a)}{ {\'AND\':\'&\',\'OR\':\'|\',\'XOR\':\'^\'}[op] }{r(b)}"\n        L.append(f" v{i}={e}")\n    L.append(" return ["+",".join("["+",".join(r(b) for b in o)+"]" for o in outs)+"]")\n    ns={}; exec("\\n".join(L),ns); return ns[\'step\']\n', 'mdcs': '# Minimal Digital Chaotic System (Nepomuceno, Lima, Arias-Garcia, Perc, Repnik,\n# Chaos, Solitons & Fractals 120 (2019) 62-66):\n#   x_{n+1} = 4 * x_n * xdc_n,  xdc = digit (one\'s) complement of x = 1 - ulp - x\n# Gate-level trick: x_i*~x_j + x_j*~x_i = x_i XOR x_j and x_i*~x_i = 0, so the\n# product needs only n(n-1)/2 XOR partial products; r = 4 is a 2-bit shift (wires).\nfrom chua_min import Net\n\ndef build(n):\n    g=Net(); X=[(\'a\',i) for i in range(n)]          # unsigned fraction, LSB first\n    cols=[[] for _ in range(2*n+1)]\n    for i in range(n):\n        for j in range(i+1,n): cols[i+j].append(g.XOR(X[i],X[j]))\n    P=[]\n    for c in range(2*n):                             # column compression, exact\n        col=cols[c]\n        while len(col)>1:\n            if len(col)>=3:\n                a,b,d=col.pop(),col.pop(),col.pop(); s=g.XOR(a,b)\n                col.append(g.XOR(s,d)); cols[c+1].append(g.OR(g.AND(a,b),g.AND(s,d)))\n            else:\n                a,b=col.pop(),col.pop(); col.append(g.XOR(a,b)); cols[c+1].append(g.AND(a,b))\n        P.append(col[0] if col else 0)\n    return g,[P[n-2:2*n-2]]                          # x\' = 4P >> n  (pure wiring)\n\ndef live(g,outs):\n    """Gates that actually drive an output (dead-code elimination)."""\n    seen=set(); st=[b for o in outs for b in o]\n    while st:\n        a=st.pop()\n        if isinstance(a,tuple) and a[0]==\'n\' and a[1] not in seen:\n            seen.add(a[1]); op,x,y=g.ops[a[1]]; st+= [x] + ([y] if y is not None else [])\n    return len(seen)\n', 'mdcs_gate': "# Gate-minimal MDCS: XOR-pair partial products, column compression,\n# optional truncation (k guard columns) with a constant bias compensation.\nfrom chua_min import Net\ndef build(n,k=None,comp=0):\n    g=Net(); X=[('a',i) for i in range(n)]\n    lo = 0 if k is None else max(0,n-2-k)\n    cols=[[] for _ in range(2*n+2)]\n    for i in range(n):\n        for j in range(i+1,n):\n            if i+j>=lo: cols[i+j].append(g.XOR(X[i],X[j]))\n    for b in range(lo, 2*n):                 # add constant 'comp' at column lo\n        if (comp>>(b-lo))&1: cols[b].append(1)\n    P=[]; fa=ha=0\n    for c in range(2*n):\n        col=cols[c]\n        while len(col)>1:\n            if len(col)>=3:\n                a,b,d=col.pop(),col.pop(),col.pop(); s=g.XOR(a,b)\n                col.append(g.XOR(s,d)); cols[c+1].append(g.OR(g.AND(a,b),g.AND(s,d))); fa+=1\n            else:\n                a,b=col.pop(),col.pop(); col.append(g.XOR(a,b)); cols[c+1].append(g.AND(a,b)); ha+=1\n        P.append(col[0] if col else 0)\n    g.fa,g.ha=fa,ha\n    return g,[P[n-2:2*n-2]]\n", 'archs': "# Gate-level backends for the architecture study, built on zoo.BitB:\n#  - exact constants: float constants are converted to the nearest simple fraction, so a\n#    constant is stored to the resolution of the word instead of to 53 bits;\n#  - carry-lookahead adder: 4-bit lookahead blocks, rippled between blocks;\n#  - array multiplier: one AND row and one adder per multiplier bit (shift-and-add,\n#    two's complement), keeping the same columns as the Booth multiplier.\nfrom fractions import Fraction\nimport zoo\n\n\ndef exact(c):\n    return Fraction(c).limit_denominator(10**7) if isinstance(c, float) else c\n\n\nclass Exact(zoo.BitB):\n    def K(s, c, W=None, F=None): return super().K(exact(c), W, F)\n    def _csd(s, c): return super()._csd(exact(c))\n\n\nclass CLA:\n    def _add(s, A, B, cin=0):\n        g = s.g; o = []; c = cin\n        for k in range(0, len(A), 4):\n            a, b = A[k:k + 4], B[k:k + 4]\n            G = [g.AND(x, y) for x, y in zip(a, b)]; P = [g.XOR(x, y) for x, y in zip(a, b)]\n            cs = [c]\n            for i in range(len(a)):\n                # c_{i+1} = G_i | P_i G_{i-1} | ... | P_i...P_0 c, flattened per bit\n                t = G[i]; pp = P[i]\n                for j in range(i - 1, -1, -1):\n                    t = g.OR(t, g.AND(pp, G[j])); pp = g.AND(pp, P[j])\n                cs.append(g.OR(t, g.AND(pp, c)))\n            o += [g.XOR(P[i], cs[i]) for i in range(len(a))]; c = cs[-1]\n        return o\n\n\nclass Array:\n    def mul(s, A, B):\n        g = s.g; W, F = s.W, s.F; HI = F + W\n        ext = lambda k: A[k] if 0 <= k < W else (A[-1] if k >= W else 0)\n        acc = [0] * HI\n        for j in range(W):\n            pp = [g.AND(ext(c - j), B[j]) for c in range(j, HI)]\n            acc[j:] = s.sub(acc[j:], pp) if j == W - 1 else s._add(acc[j:], pp)\n        return acc[F:HI]\n\n\nARCHS = {\n    'ripple + Booth': Exact,\n    'CLA + Booth': type('CB', (CLA, Exact), {}),\n    'ripple + array': type('RA', (Array, Exact), {}),\n    'CLA + array': type('CA', (CLA, Array, Exact), {}),\n}\n"}
