import sys, types, math, json, random, argparse
import numpy as np
def _load(name):
    m=types.ModuleType(name); sys.modules[name]=m; exec(compile(_SRC[name],name+'.py','exec'),m.__dict__); return m
for _n in ['chua_min','zoo','mdcs','mdcs_gate','archs']: _load(_n)
import zoo, mdcs, mdcs_gate, archs
live=mdcs.live
def ok(got,ref,tol=0.005): return 'OK ' if abs(got-ref)<=tol*max(1,abs(ref)) else 'DIFF'
def head(t): print('\n'+'='*72+'\n'+t+'\n'+'='*72)
TABLE=[('Gingerbreadman',zoo.gingerbread,5,2,450),('Lozi',zoo.lozi,3,2,754),('Tent',zoo.tent,2,1,879),
       ('Logistic',zoo.logistic,2,1,23705),('Chua',zoo.chua,4,3,22647),
       ('Rossler',zoo.rossler,10,3,31925),('Lorenz',zoo.lorenz,12,3,53799)]
M_C={'Gingerbreadman':(0,0),'Lozi':(0,0),'Tent':(0,0),'MDCS':(1,0),'Logistic':(1,0),'Chua':(0,3),'Rossler':(1,1),'Lorenz':(2,1)}
LUTS={'Gingerbreadman':450,'Lozi':758,'Tent':915,'MDCS':6838,'Logistic':23994,'Chua':25724,'Rossler':29704,'Lorenz':49450}
FID={'Gingerbreadman':(0.282,0.034),'Lozi':(0.002,0.003),'Tent':(1.10e-8,0.004),'MDCS':(5.83e-5,0.0031),
     'Logistic':(0.009,0.004),'Chua':(0.016,0.124),'Rossler':(0.036,0.002),'Lorenz':(0.016,0.093)}
def L_of(fn,n,I,nv,cls=None):
    cls=cls or zoo.BitB; B=cls(n,I); st=[[(chr(97+v),i) for i in range(n)] for v in range(nv)]
    return live(B.g,fn(B,*st))
def L_mdcs(n): g,o=mdcs_gate.build(n,2,5); return live(g,o)
def table1():
    head('Table 1: gate counts (ripple + Booth, float64 constants), fits over n = 16..64')
    NS=[16,24,32,48,64]; res={}
    for name,fn,I,nv,ref in TABLE:
        L=[L_of(fn,n,I,nv) for n in NS]; res[name]=L
        p=np.polyfit(NS,L,1 if M_C[name]==(0,0) else 2)
        print(f"{name:15s} M,C={M_C[name]} fit={np.round(p,2)} L(64)={L[-1]} paper={ref} {ok(L[-1],ref,0)} LUT={LUTS[name]} ({100*(LUTS[name]/L[-1]-1):+.0f}%)")
    L=[L_mdcs(n) for n in NS]; res['MDCS']=L
    print(f"{'MDCS':15s} M,C=(1, 0) fit={np.round(np.polyfit(NS,L,2),2)} L(64)={L[-1]} paper=6432 {ok(L[-1],6432,0)} LUT={LUTS['MDCS']} ({100*(LUTS['MDCS']/L[-1]-1):+.0f}%)")
    x=np.log([res[k][-1] for k in LUTS]); y=np.log(list(LUTS.values()))
    print(f"LUT vs gates log-log: slope={np.polyfit(x,y,1)[0]:.2f} (paper 0.99) R2={np.corrcoef(x,y)[0,1]**2:.3f} (paper 0.999)")
def units(cls,NS):
    from fractions import Fraction as Fr
    def u(w,n,I=4):
        B=cls(n,I); x=[('a',i) for i in range(n)]; y=[('b',i) for i in range(n)]
        return live(B.g,[B.mul(x,y) if w=='p' else B.lin(zoo.Z(B),[(x,Fr(1,5))])])
    return np.polyfit(NS,[u('p',n) for n in NS],2)[0], np.polyfit(NS,[u('c',n) for n in NS],2)[0]
def law():
    head('Gate-count law: a (one product), b (one non-dyadic constant, rho = 1/2)')
    a,b=units(archs.Exact,[16,32,48,64,96,128,192,256])
    print(f"a={a:.3f} (paper 5.75) {ok(a,5.75)}  b={b:.3f} (paper 2.5) {ok(b,2.5)}")
    for nm,(M,C) in [('Logistic',(1,0)),('Rossler',(1,1)),('Lorenz',(2,1))]: print(f"  predicted n^2 coefficient {nm}: {5.75*M+2.5*C:.2f}")
def tent_rule():
    head('Design rule: tent map mu = 1.99 (float64) vs mu = 2 - 2^-7')
    t199=lambda B,x:[B.lin(zoo.Z(B),[(B.sub(B.K(.5),B.abs(B.sub(x,B.K(.5)))),1.99)])]
    g1=L_of(t199,64,2,1); g2=L_of(zoo.tent,64,2,1)
    print(f"L(64): {g1} (paper 5571) {ok(g1,5571,0)} -> {g2} (paper 879) {ok(g2,879,0)}; factor {g1/g2:.1f}, reduction {100*(1-g2/g1):.0f}%")
    print(f"lambda = ln mu: {math.log(1.99):.4f} -> {math.log(2-2**-7):.4f}")
def arch_swap():
    head('Architecture swap: (a, b) and bitwise equivalence at 32 bits')
    for an,cls in archs.ARCHS.items():
        a,b=units(cls,[16,32,48,64,96,128]); same=True
        for name,fn,I,nv,_ in TABLE:
            def comp(c):
                B=c(32,I); st=[[(chr(97+v),i) for i in range(32)] for v in range(nv)]
                return zoo.compile_net(B,fn(B,*st),nv)
            r,t=comp(archs.Exact),comp(cls); rnd=random.Random(1)
            for _ in range(20):
                s=[[rnd.getrandbits(1) for _ in range(32)] for _ in range(nv)]; same&=r(*s)==t(*s)
        print(f"{an:15s} a={a:6.3f} b={b:5.3f} bitwise equal: {same}")
    print("paper: (5.75,2.5) (9.125,4.75) (8.5,2.5) (15.25,4.75)")
def fig1(plot):
    head('Fig. 1: L(n), exact constants, n = 16..256')
    NS=[16,24,32,48,64,96,128,192,256]; d={}
    for name,fn,I,nv,_ in TABLE: d[name]=[L_of(fn,n,I,nv,archs.Exact) for n in NS]
    d['MDCS']=[L_mdcs(n) for n in NS]
    for k,v in d.items(): print(f"  {k:15s} log-log slope 128..256 = {np.polyfit(np.log(NS[-3:]),np.log(v[-3:]),1)[0]:.2f}")
    if plot:
        import matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
        f,ax=plt.subplots(figsize=(3.4,2.8))
        for k,v in d.items(): ax.loglog(NS,v,'o-',ms=3,lw=1,label=k)
        n=np.array(NS); ax.loglog(n,8*n,'k--',lw=.6); ax.loglog(n,6*n**2,'k--',lw=.6)
        ax.set_xlabel('word width n (bits)'); ax.set_ylabel('gates per iteration'); ax.legend(fontsize=5)
        f.tight_layout(); f.savefig('fig1_Ln.pdf'); print('wrote fig1_Ln.pdf')
def fig2(plot):
    head('Fig. 2: energy per output bit vs gates per state bit (stored 64-bit results)')
    xs,ys,cs=[],[],[]
    for name,scheme,cl,flags,L64,pj in ENERGY:
        if '\u26a0' in flags or not L64 or not pj: continue
        xs.append(L64/64); ys.append(pj); cs.append(cl)
    lx,ly=np.log10(xs),np.log10(ys); k,c=np.polyfit(lx,ly,1)
    print(f"N={len(xs)} (paper 114) slope={k:.2f} (paper 0.96) R2={np.corrcoef(lx,ly)[0,1]**2:.2f} (paper 0.99)")
    if plot:
        import matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
        f,ax=plt.subplots(figsize=(3.4,2.8)); col={'L':'#2a78d6','P':'#eb6834','D':'#eb6834','T':'#1baf7a'}
        ax.scatter(xs,ys,s=6,c=[col.get(q,'grey') for q in cs])
        xx=np.logspace(np.log10(min(xs)),np.log10(max(xs))); ax.plot(xx,10**c*xx**k,'k-',lw=.7)
        ax.set_xscale('log'); ax.set_yscale('log'); ax.set_xlabel('gates per state bit'); ax.set_ylabel('energy per output bit (pJ)')
        f.tight_layout(); f.savefig('fig2_energy.pdf'); print('wrote fig2_energy.pdf')
def fidelity():
    head('Fidelity, 64-bit circuit vs float64 (stored long-run results)')
    for k,(l,d) in FID.items(): print(f"{k:15s} Lyapunov rel. err={l:.3g}  distribution err={d:.3g}")
